// Get extracted events from Airtop
const response = $input.first().json;
let events = [];

// Try to get events from the parsed response
if (response.data?.modelResponse) {
  const modelResponse = response.data.modelResponse;

  // If it's already parsed as JSON
  if (typeof modelResponse === 'object' && modelResponse.events) {
    events = modelResponse.events;
  } 
  // If it's a string, try to parse it
  else if (typeof modelResponse === 'string') {
    try {
      const parsed = JSON.parse(modelResponse);
      events = parsed.events || [];
    } catch (e) {
      console.log('Could not parse model response as JSON');
    }
  }
}

// Calculate date range (next 3 weeks)
const today = new Date();
const threeWeeksFromNow = new Date(today);
threeWeeksFromNow.setDate(today.getDate() + 21);

// Filter events that contain "queer" in description or title
const filteredEvents = events.filter(event => {
  const searchText = ((event.title || '') + ' ' + (event.description || ''));
  const hasQueer = searchText.toLowerCase().includes('queer');

  // Check date range if date is available
  if (event.date && hasQueer) {
    try {
      const eventDate = new Date(event.date);
      return eventDate >= today && eventDate <= threeWeeksFromNow;
    } catch {
      return hasQueer; // Include if date can't be parsed but has queer
    }
  }

  return hasQueer;
});

// Return formatted events
return filteredEvents.map(event => ({
  json: {
    title: event.title || 'Untitled Event',
    date: event.date || 'Date TBD',
    venue: event.venue || 'Venue TBD',
    description: event.description || '',
    link: event.url || event.link || '',
    location: 'Berlin'
  }
}));
